# Build the iOS 6 Xcode package: dist\BaldiCpp-iOS\ (+ dist\BaldiCpp-iOS.zip to copy into the Mac VM).
#   BaldiCpp.xcodeproj\   generated by tools\gen-xcodeproj.py (self-validating)
#   BaldiCpp\             iOS shell (ios\BaldiCpp: *.mm, Info.plist, Images\)
#   src\                  engine + game sources (the Windows shell, sim and smoke are left out)
#   content\data\         the SAME game data the Windows package ships (dist\BaldiCpp\content\data)
#   HOW-TO-BUILD.txt      step by step, for someone new to Xcode
# Run tools\package.ps1 first (it stages content\data). usage: tools\package-ios.ps1 [-NoZip]
param([switch]$NoZip)
$ErrorActionPreference = 'Stop'
$port = Split-Path -Parent $PSScriptRoot
$pkg = Join-Path $port 'dist\BaldiCpp-iOS'
$content = Join-Path $port 'dist\BaldiCpp\content\data'
if (-not (Test-Path $content)) { throw "no $content -- run tools\package.ps1 first" }
if (Test-Path $pkg) { Remove-Item -Recurse -Force $pkg }
New-Item -ItemType Directory -Force -Path (Join-Path $pkg 'src\game') | Out-Null

Copy-Item -Recurse (Join-Path $port 'ios\BaldiCpp') (Join-Path $pkg 'BaldiCpp')
$cpp = @('quat-euler','eng-core','eng-rewired','eng-json','eng-scene','eng-mesh','game-actions','bindings',
         'render-gl','render-scene','app-core')
foreach ($c in $cpp) { Copy-Item (Join-Path $port "src\$c.cpp") (Join-Path $pkg 'src') }
Get-ChildItem (Join-Path $port 'src') -Filter *.h | ForEach-Object { Copy-Item $_.FullName (Join-Path $pkg 'src') }
Get-ChildItem (Join-Path $port 'src\game') -Filter *.hpp | ForEach-Object { Copy-Item $_.FullName (Join-Path $pkg 'src\game') }
Write-Host 'copying game data...'
New-Item -ItemType Directory -Force -Path (Join-Path $pkg 'content') | Out-Null
Copy-Item -Recurse $content (Join-Path $pkg 'content\data')
Copy-Item (Join-Path $port 'ios\HOW-TO-BUILD.txt') $pkg
# one-click device build -> BaldiCpp.ipa on the Mac (zip-posix.py marks *.command executable)
Copy-Item (Join-Path $port 'ios\make-ipa.command') $pkg

python3 (Join-Path $port 'tools\gen-xcodeproj.py') $pkg
if ($LASTEXITCODE -ne 0) { throw 'gen-xcodeproj failed' }

$files = (Get-ChildItem -Recurse -File $pkg | Measure-Object -Property Length -Sum)
Write-Host ("  {0} files, {1:N0} MB" -f $files.Count, ($files.Sum / 1MB))
if (-not $NoZip) {
  $zip = Join-Path $port 'dist\BaldiCpp-iOS.zip'
  if (Test-Path $zip) { Remove-Item -Force $zip }
  Write-Host 'zipping...'
  # Not Compress-Archive: on Windows PowerShell 5.1 it writes '\' entry names, which the Mac unzips
  # into flat files named "BaldiCpp-iOS\BaldiCpp.xcodeproj\project.pbxproj".
  python3 (Join-Path $port 'tools\zip-posix.py') $pkg $zip
  if ($LASTEXITCODE -ne 0) { throw 'zip-posix failed' }
  Write-Host ("IOS PACKAGE OK - {0} ({1:N0} MB)" -f $zip, ((Get-Item $zip).Length / 1MB))
} else {
  Write-Host "IOS PACKAGE OK - $pkg"
}
